import math
def priority(task, state, k=0.5, late_boost=5.0, w_atc=1.0, m=2.0, age=0.1, res_p=0.0,
             map_mult=1.0, reduce_mult=1.0, join_mult=1.0, other_mult=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = task.due - state.now - est
    late = max(0.0, -slack)
    atc = (task.weight / est) * math.exp(-max(0.0, slack) / max(k * mean_est, 1e-6))
    wait = state.now - task.release
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'map':
        typ = map_mult
    elif task.task_type == 'reduce':
        typ = reduce_mult
    elif task.task_type == 'join':
        typ = join_mult
    else:
        typ = other_mult
    block = max(task.resource_need, 1e-6) ** res_p
    return typ * tier * (w_atc * atc + late_boost * task.weight * late / est + age * wait / est) / block  # tuned (k=0.329,late_boost=7.25,w_atc=1.57,m=1.09,age=0.116,res_p=0,map_mult=3.96,reduce_mult=0.811,join_mult=2.46,other_mult=0.631)

def priority(task, state, c=1.0, m=2.0, big=1e6):
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - state.now - est
    tier = m if task.tenant == 'premium' else 1.0
    if slack < 0:
        lateness = -slack
        return big + tier * task.weight / est * (1.0 + c * lateness / max(state.mean_est, 1e-6))
    else:
        return -max(task.due, state.now + est)

def priority(task, state, w=5.0, a=1.0, b=10.0, m=1.1):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    wait = max(0.0, state.now - task.release)
    return -task.due + w * tier * task.weight + a * wait / mean + b * tier / est  # tuned (w=3.54,a=2.02,b=19.2,m=0.864)

import math
def priority(task, state, b=0.5, k=1.0, c=2.0, guard=4.0):
    p = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    mean = max(state.mean_est, 1e-6)
    base = task.weight / p * (1.0 + b * wait / p)
    slack = task.due - state.now - p
    if slack <= 0.0:
        base += guard * task.weight / p * (1.0 + (-slack) / mean)
    else:
        kk = max(k, 1e-6)
        base += c * task.weight / p * math.exp(-slack / (kk * mean))
    return base  # tuned (b=0.217,k=0.521,c=1.23,guard=4.16)
